{
  "root_causes": [
    {
      "service": "ts-auth-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_request_method, attr_http_response_status_code, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'ts-auth-service' AND attr_span_kind = 'Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Auth's outgoing client calls are GET, but 2118 of them return HTTP 405 with Error status in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_request_method, attr_http_response_status_code, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'ts-verification-code-service' AND attr_span_kind = 'Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "Verification-code receives 2118 'PUT /error' requests answered 405, while its normal GET verify spans still return 200."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE service_name = 'ts-verification-code-service' AND level = 'WARN' GROUP BY ALL",
          "claim": "Verification-code logs 'Request method PUT not supported' 2118 times in the abnormal window, matching the auth calls."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_http_response_status_code, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'ts-auth-service' AND attr_span_kind = 'Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "Auth's login server spans return HTTP 500 with Error status for 2118 requests, almost all requests in the window."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-auth-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code, attr_status_code, count(*) AS n, round(avg(duration)/1e6,1) AS avg_ms FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND attr_span_kind = 'Server' AND span_name = 'POST /api/v1/users/login' GROUP BY ALL ORDER BY n DESC",
          "claim": "Ui-dashboard login requests fail with 500 (120 Error, avg about 3.6s) while its other requests stay normal."
        }
      ]
    }
  ]
}
